import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice returns a draft invoice with product details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for missing issueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for bad date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for missing lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for invalid SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRD-999', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = { qty: 3, unitPrice: 8500 };
  assert.equal(lineTotal(line), 25500);
});

test('lineTotal works with 1 qty', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.equal(lineTotal(line), 8500);
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
      { qty: 3, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 1 * 9500 + 3 * 6000);
  assert.equal(totals.subtotal, 44500);
});

test('invoiceTotals sets total equal to subtotal', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns whole cents', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 37 },
      { qty: 2, unitPrice: 249 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 37 + 2 * 249);
  assert.equal(totals.total, 535);
});

test('addLine adds a new line to an invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = addLine(inv.value, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 2);
});

test('addLine increments qty if SKU already exists', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r = addLine(inv.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine reports QTY_INVALID for non-integer qty', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = addLine(inv.value, { sku: 'DEV-HOUR', qty: 1.5 });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports QTY_INVALID for zero qty', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = addLine(inv.value, { sku: 'DEV-HOUR', qty: 0 });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for invalid SKU', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = addLine(inv.value, { sku: 'INVALID-SKU', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT if invoice is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'finalized',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(inv, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate input invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invCopy = JSON.parse(JSON.stringify(inv.value));
  addLine(inv.value, { sku: 'DEV-HOUR', qty: 2 });
  assert.deepEqual(inv.value, invCopy);
});

test('removeLine removes a line from an invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  const r = removeLine(inv.value, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND if SKU not on invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = removeLine(inv.value, 'DEV-HOUR');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = removeLine(inv.value, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT if invoice is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'finalized',
    lines: [
      { sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 2, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };
  const r = removeLine(inv, 'DEV-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate input invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  const invCopy = JSON.parse(JSON.stringify(inv.value));
  removeLine(inv.value, 'DEV-HOUR');
  assert.deepEqual(inv.value, invCopy);
});

test('issueInvoice assigns a number and changes status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r = issueInvoice(inv.value, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
  assert.equal(r.value.status, 'issued');
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.lines.length, 1);
});

test('issueInvoice generates the next number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(inv.value, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice reports NOT_DRAFT if invoice is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = issueInvoice(inv, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate input invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invCopy = JSON.parse(JSON.stringify(inv.value));
  issueInvoice(inv.value, []);
  assert.deepEqual(inv.value, invCopy);
});

