    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.total, 15300);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 8500, discountPercent: 10 },
      { qty: 1, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 18000);
  assert.equal(totals.discount, 850 + 1900);
  assert.equal(totals.total, 18000 - 2750);
});

